/* ------------------ text cleanup for Amor's replies ------------------ */
const cleanText = (s) =>
  (s || "")
    .replace(/\*\*/g, "")
    .replace(/\*/g, "")
    .replace(/^#+\s*/gm, "")
    .replace(/\s*[—–]\s*/g, ", ")
    .replace(/,\s*,/g, ",");

