/* ---- SELF-HOST STORAGE ----
   Saves locally on the tablet AND mirrors to the central database
   (Supabase via /api/log) when the backend env vars are configured.
   Each tablet gets a device id so central data never collides. */
const DEVICE_ID = (() => {
  try {
    let d = localStorage.getItem("amor-device");
    if (!d) { d = "t" + Math.random().toString(36).slice(2, 10); localStorage.setItem("amor-device", d); }
    return d;
  } catch (e) { return "tablet"; }
})();
const store = {
  async get(key) {
    try { const v = localStorage.getItem(key); if (v != null) return { value: v }; } catch (e) {}
    return null;
  },
  async set(key, value) {
    try { localStorage.setItem(key, value); } catch (e) {}
    try {
      fetch("/api/log", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ key: `${key}::${DEVICE_ID}`, value }),
      }).catch(() => {});
    } catch (e) {}
    return { key, value };
  },
};

export default function AmorBooth() {
  const [lang, setLang] = useState("pt");
  const [screen, setScreen] = useState("welcome"); // welcome | attract | join | home | answer | quiz | admin
  const [showSteps, setShowSteps] = useState(null); // null | page index into GUIDE_IMGS
  const [showVideos, setShowVideos] = useState(null); // null | index into VIDEOS (or 0 when empty)
  const [visitor, setVisitor] = useState(null);
  const [form, setForm] = useState({ name: "", country: "", org: "", email: "", phone: "", consent: false });
  const [draft, setDraft] = useState("");
  const [chat, setChat] = useState([]); // running conversation: {role:'you'|'amor', text}
  const [loading, setLoading] = useState(false);
  const [history, setHistory] = useState([]); // API-format history
  const chatEndRef = useRef(null);
  const [leads, setLeads] = useState([]);
  const [qLog, setQLog] = useState([]);
  const [guideReqs, setGuideReqs] = useState([]); // requests for the emailed FC2 booklet
  const [guideAskEmail, setGuideAskEmail] = useState(false);
  const [guideEmailDraft, setGuideEmailDraft] = useState("");
  const [adminTaps, setAdminTaps] = useState(0);
  const tapTimer = useRef(null);
  /* quiz state */
  const [quizCards, setQuizCards] = useState([]); // shuffled indices into quizSteps
  const [picks, setPicks] = useState([]); // card indices in picked order
  const [quizResult, setQuizResult] = useState(null); // null | 'win' | array of booleans
  const t = T[lang];

  /* ---- load stored data ---- */
  useEffect(() => {
    (async () => {
      try {
        const r = await store.get("amor-leads");
        if (r?.value) setLeads(JSON.parse(r.value));
      } catch (e) {}
      try {
        const r = await store.get("amor-questions");
        if (r?.value) setQLog(JSON.parse(r.value));
      } catch (e) {}
      try {
        const r = await store.get("amor-guide-requests");
        if (r?.value) setGuideReqs(JSON.parse(r.value));
      } catch (e) {}
    })();
  }, []);

  /* ---- keep the chat scrolled to the newest message ---- */
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [chat, loading]);

  const saveLeads = async (arr) => {
    setLeads(arr);
    try { await store.set("amor-leads", JSON.stringify(arr)); } catch (e) {}
  };
  const saveQLog = async (arr) => {
    setQLog(arr);
    try { await store.set("amor-questions", JSON.stringify(arr)); } catch (e) {}
  };
  const saveGuideReqs = async (arr) => {
    setGuideReqs(arr);
    try { await store.set("amor-guide-requests", JSON.stringify(arr)); } catch (e) {}
  };

  /* ---- request the emailed FC2 booklet ---- */
  const requestGuide = (email) => {
    const em = (email || "").trim();
    if (!em || !/[^@\s]+@[^@\s]+\.[^@\s]+/.test(em)) return;
    const entry = { ts: new Date().toISOString(), name: visitor?.name || "", country: visitor?.country || "", email: em, lang };
    saveGuideReqs([...guideReqs, entry]);
    try {
      fetch("/api/send-guide", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: em, name: visitor?.name || "", lang }),
      }).catch(() => {});
    } catch (e) {}
    setChat((c) => [...c, { role: "amor", text: t.guideSent(em) }]);
    setGuideAskEmail(false);
    setGuideEmailDraft("");
  };

  /* ---- hidden admin: tap footer 5x ---- */
  const footerTap = () => {
    clearTimeout(tapTimer.current);
    const n = adminTaps + 1;
    if (n >= 5) { setAdminTaps(0); setScreen("admin"); return; }
    setAdminTaps(n);
    tapTimer.current = setTimeout(() => setAdminTaps(0), 1500);
  };

  /* ---- ask Amor (continuous conversation) ---- */
  const ask = useCallback(async (q) => {
    const query = (q || "").trim();
    if (!query || loading) return;
    setLoading(true);
    setScreen("answer");
    setChat((c) => [...c, { role: "you", text: query }]);

    const visitorCtx = visitor
      ? `\nVISITOR CONTEXT: You are chatting with ${visitor.name ? visitor.name.split(" ")[0] : "a visitor"}${visitor.country ? `, who told us at registration that they are from ${visitor.country}` : ""}. Use this when they ask about availability in "my country". Do not ask for information you already have here.`
      : "\nVISITOR CONTEXT: This visitor skipped registration, so you do not know their country. If needed, ask them to type it in the chat box below.";
    const LANG_NAMES = {
      en: "English",
      pt: "Brazilian Portuguese",
      es: "Latin American Spanish",
      sw: "Swahili (Kiswahili)",
      fr: "French",
      sn: "Shona (chiShona)",
      nd: "Ndebele (isiNdebele as spoken in Zimbabwe)",
      yo: "Yoruba",
    };
    const sys = KNOWLEDGE.replace("{{LANG}}", LANG_NAMES[lang] || "English") + visitorCtx;
    const msgs = [...history, { role: "user", content: query }].slice(-12);

    try {
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ system: sys, messages: msgs }),
      });
      const data = await res.json();
      const raw = (data.text || "").trim();
      if (!raw) throw new Error("empty");
      const text = cleanText(raw);
      setChat((c) => [...c, { role: "amor", text }]);
      setHistory([...msgs, { role: "assistant", content: text }].slice(-10));
      const entry = { ts: new Date().toISOString(), lang, question: query, answer: text, visitor: visitor?.name || "", country: visitor?.country || "" };
      saveQLog([...qLog, entry]);
    } catch (e) {
      setChat((c) => [...c, { role: "amor", text: t.errorMsg }]);
    } finally {
      setLoading(false);
    }
  }, [lang, history, loading, visitor, qLog, t.errorMsg]);

  /* ---- registration ---- */
  const submitJoin = () => {
    if (!form.name.trim() || !form.country.trim()) return;
    const lead = { ...form, ts: new Date().toISOString(), lang };
    setVisitor(lead);
    saveLeads([...leads, lead]);
    setScreen("home");
  };

  const resetForNewVisitor = () => {
    setVisitor(null);
    setForm({ name: "", country: "", org: "", email: "", phone: "", consent: false });
    setHistory([]);
    setChat([]);
    setDraft("");
    setGuideAskEmail(false);
    setGuideEmailDraft("");
    setShowSteps(null);
    setShowVideos(null);
    setScreen("welcome");
  };

  /* "Goodbye Amor!": a warm sign-off with the team referral, then back to welcome for the next delegate */
  const sayGoodbye = () => {
    setChat((c) => [...c, { role: "amor", text: t.goodbyeMsg }]);
    setTimeout(resetForNewVisitor, 5000);
  };

  /* ---- quiz ---- */
  const startQuiz = () => {
    /* Shuffle until well mixed: no card in its correct spot, no two
       consecutive steps adjacent, and a big total displacement. */
    let idx = [0, 1, 2, 3, 4, 5];
    let tries = 0;
    do {
      idx = [0, 1, 2, 3, 4, 5];
      for (let i = idx.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [idx[i], idx[j]] = [idx[j], idx[i]];
      }
      tries++;
      const noFixed = idx.every((v, i) => v !== i);
      const noRuns = idx.every((v, i) => i === 0 || idx[i - 1] !== v - 1);
      const spread = idx.reduce((s, v, i) => s + Math.abs(v - i), 0) >= 12;
      if ((noFixed && noRuns && spread) || tries > 200) break;
    } while (true);
    setQuizCards(idx);
    setPicks([]);
    setQuizResult(null);
    setScreen("quiz");
  };
  const togglePick = (cardIdx) => {
    if (quizResult === "win") return;
    setQuizResult(null);
    setPicks((p) => (p.includes(cardIdx) ? p.filter((x) => x !== cardIdx) : p.length < 6 ? [...p, cardIdx] : p));
  };
  const checkQuiz = () => {
    if (picks.length < 6) return;
    const marks = quizCards.map((stepIdx) => picks.indexOf(stepIdx) === stepIdx);
    const win = marks.every(Boolean);
    setQuizResult(win ? "win" : marks);
  };

  const downloadCSV = (rows, headers, filename) => {
    const esc = (v) => `"${String(v ?? "").replace(/"/g, '""')}"`;
    const csv = [headers.join(","), ...rows.map((r) => headers.map((h) => esc(r[h])).join(","))].join("\n");
    const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  };

  const frameProps = { t, onFooterTap: footerTap };

  /* ---- shared overlays: on-screen how-to steps + video reel ---- */
  const overlayShell = (children, onClose) => (
    <div
      onClick={onClose}
      style={{ position: "fixed", inset: 0, background: "rgba(74,16,51,.82)", zIndex: 50, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}
    >
      <div onClick={(e) => e.stopPropagation()} style={{ background: C.white, border: `4px solid ${C.plum}`, borderRadius: 24, boxShadow: `0 10px 0 ${C.deep}`, maxWidth: 860, width: "100%", maxHeight: "92vh", display: "flex", flexDirection: "column", overflow: "hidden" }}>
        {children}
      </div>
    </div>
  );

  const overlays = (
    <>
      {showSteps != null && overlayShell(
        <>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "12px 18px", background: C.magenta, color: C.white }}>
            <div className="amor-display" style={{ fontSize: 20 }}>{t.stepsTitle} · {showSteps + 1}/{GUIDE_IMGS.length}</div>
            <button className="amor-btn amor-display" onClick={() => setShowSteps(null)} style={{ background: C.white, color: C.plum, border: `3px solid ${C.plum}`, borderRadius: 999, padding: "6px 16px", fontSize: 14 }}>
              ✕ {t.close}
            </button>
          </div>
          <div style={{ overflowY: "auto", flex: 1, background: C.pinkLight }}>
            <img src={GUIDE_IMGS[showSteps]} alt={t.stepsTitle} style={{ width: "100%", height: "auto", display: "block" }} />
          </div>
          <div style={{ display: "flex", gap: 12, justifyContent: "center", padding: 12 }}>
            <BigButton small color={C.purple} onClick={() => setShowSteps((s) => Math.max(0, s - 1))}>←</BigButton>
            {GUIDE_IMGS.map((_, i) => (
              <button key={i} className="amor-btn" onClick={() => setShowSteps(i)} style={{ width: 18, height: 18, borderRadius: "50%", border: `3px solid ${C.plum}`, background: showSteps === i ? C.magenta : C.white }} />
            ))}
            <BigButton small color={C.purple} onClick={() => setShowSteps((s) => Math.min(GUIDE_IMGS.length - 1, s + 1))}>→</BigButton>
          </div>
        </>,
        () => setShowSteps(null)
      )}
      {showVideos != null && overlayShell(
        <>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "12px 18px", background: C.purple, color: C.white }}>
            <div className="amor-display" style={{ fontSize: 20 }}>
              ▶ {t.videosTitle}{VIDEOS.length > 0 ? ` · ${showVideos + 1}/${VIDEOS.length}` : ""}
            </div>
            <button className="amor-btn amor-display" onClick={() => setShowVideos(null)} style={{ background: C.white, color: C.plum, border: `3px solid ${C.plum}`, borderRadius: 999, padding: "6px 16px", fontSize: 14 }}>
              ✕ {t.close}
            </button>
          </div>
          <div style={{ flex: 1, background: C.plum, display: "flex", alignItems: "center", justifyContent: "center", minHeight: 300 }}>
            {VIDEOS.length === 0 ? (
              <div className="amor-display" style={{ color: C.white, fontSize: 22, padding: 30, textAlign: "center" }}>{t.videosNone}</div>
            ) : /youtube\.com|youtu\.be|vimeo\.com/.test(VIDEOS[showVideos].url) ? (
              <iframe
                title={VIDEOS[showVideos].title || "video"}
                src={VIDEOS[showVideos].url}
                style={{ width: "100%", aspectRatio: "16/9", border: "none" }}
                allow="autoplay; fullscreen"
                allowFullScreen
              />
            ) : (
              <video key={VIDEOS[showVideos].url} src={VIDEOS[showVideos].url} controls autoPlay style={{ width: "100%", maxHeight: "70vh" }} />
            )}
          </div>
          {VIDEOS.length > 1 && (
            <div style={{ display: "flex", gap: 12, justifyContent: "center", padding: 12 }}>
              <BigButton small color={C.purple} onClick={() => setShowVideos((v) => (v - 1 + VIDEOS.length) % VIDEOS.length)}>←</BigButton>
              <BigButton small color={C.purple} onClick={() => setShowVideos((v) => (v + 1) % VIDEOS.length)}>→</BigButton>
            </div>
          )}
        </>,
        () => setShowVideos(null)
      )}
    </>
  );

  /* ================= SCREENS ================= */

  /* ---- WELCOME: plain landing with language choice ---- */
  if (screen === "welcome") {
    const greetings = "WELCOME · BEM-VINDO · BIENVENIDO · KARIBU · BIENVENUE · MAUYA · SIYALEMUKELA · Ẹ KÁÀBỌ̀";
    return (
      <Frame {...frameProps}>
        <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "40px 24px", textAlign: "center" }}>
          <div className="amor-rise amor-display" style={{ fontSize: "clamp(52px, 9vw, 110px)", color: C.magenta, lineHeight: 1, textShadow: `4px 4px 0 ${C.white}` }}>
            WELCOME
          </div>
          <div className="amor-rise-2 amor-body" style={{ fontSize: 15, fontWeight: 800, marginTop: 12, letterSpacing: ".08em", textTransform: "uppercase", color: C.plum, opacity: 0.8, maxWidth: 640 }}>
            {greetings}
          </div>
          <div className="amor-rise-3" style={{ display: "flex", gap: 12, flexWrap: "wrap", justifyContent: "center", marginTop: 34, maxWidth: 720 }}>
            {LANGS.map(([code, label], i) => (
              <button
                key={code}
                className="amor-btn amor-display"
                onClick={() => { setLang(code); setScreen("attract"); }}
                style={{
                  background: [C.magenta, C.purple, C.yellow, C.white][i % 4],
                  color: [C.white, C.white, C.plum, C.plum][i % 4],
                  border: `4px solid ${C.plum}`,
                  borderRadius: 999,
                  boxShadow: `0 6px 0 ${C.plum}`,
                  fontSize: 20,
                  padding: "14px 30px",
                }}
              >
                {label}
              </button>
            ))}
          </div>
        </div>
      </Frame>
    );
  }

  /* ---- ATTRACT ---- */
  if (screen === "attract") {
    return (
      <Frame bgImage={IMG_BG} {...frameProps}>
        <div style={{ position: "absolute", top: 20, right: 20, zIndex: 5 }}>
          <LangToggle lang={lang} setLang={setLang} />
        </div>
        <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", flexWrap: "wrap", gap: 20, padding: "40px 24px 10px", position: "relative" }}>
          <div className="amor-rise" style={{ textAlign: "center", maxWidth: 560 }}>
            <div className="amor-display" style={{ fontSize: "clamp(30px, 5vw, 52px)", color: C.plum, lineHeight: 1 }}>
              {t.attractHi}
            </div>
            <div className="amor-script" style={{ fontSize: "clamp(90px, 16vw, 190px)", color: C.magenta, lineHeight: 1, textShadow: `4px 4px 0 ${C.white}` }}>
              Amor!
            </div>
            <div className="amor-rise-2" style={{ fontSize: "clamp(18px, 2.4vw, 26px)", fontWeight: 800, marginTop: 10, color: C.plum }}>
              {t.attractSub}
            </div>
            <div className="amor-rise-3" style={{ marginTop: 26 }}>
              <BigButton onClick={() => setScreen("join")}>{t.start} →</BigButton>
            </div>
          </div>
          <div className="amor-rise-2" style={{ display: "flex", alignItems: "flex-end", gap: 0 }}>
            <Mascot pose="wave" size={320} />
            <div className="amor-rise-3" style={{ marginLeft: -30, marginBottom: 26 }}>
              <LoveHeart text={t.attractTag} />
            </div>
          </div>
        </div>
      </Frame>
    );
  }

  /* ---- JOIN ---- */
  if (screen === "join") {
    const inputStyle = {
      width: "100%", padding: "15px 18px", fontSize: 19, border: `3px solid ${C.plum}`,
      background: C.white, color: C.plum, marginBottom: 13, boxSizing: "border-box",
    };
    const canGo = form.name.trim() && form.country.trim();
    return (
      <Frame {...frameProps}>
        <div style={{ position: "absolute", top: 20, right: 20, zIndex: 5 }}>
          <LangToggle lang={lang} setLang={setLang} />
        </div>
        <FlowerSpin size={300} opacity={0.35} style={{ position: "absolute", top: -110, left: -110 }} />
        <FlowerSpin size={260} opacity={0.35} style={{ position: "absolute", bottom: -90, right: -90 }} />
        <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 10, padding: "36px 20px", flexWrap: "wrap" }}>
          <div className="amor-rise" style={{ width: "100%", maxWidth: 600, background: C.white, border: `4px solid ${C.plum}`, borderRadius: 28, boxShadow: `0 10px 0 ${C.pinkMid}`, padding: "32px 32px" }}>
            <div className="amor-display" style={{ fontSize: "clamp(26px, 4vw, 38px)", lineHeight: 1.05, color: C.magenta }}>
              {t.joinTitle}
            </div>
            <p style={{ fontSize: 16, fontWeight: 700, margin: "8px 0 20px" }}>{t.joinSub}</p>
            <input className="amor-input" style={inputStyle} placeholder={t.name + " *"} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
            <select
              className="amor-input"
              style={{ ...inputStyle, appearance: "auto", cursor: "pointer", color: form.country ? C.plum : "#9b7f8f" }}
              value={form.country}
              onChange={(e) => setForm({ ...form, country: e.target.value })}
            >
              <option value="" disabled>{t.countryPick}</option>
              {(COUNTRIES[lang] || COUNTRIES.en).map((c) => (
                <option key={c} value={c}>{c}</option>
              ))}
              <option value={t.countryOther}>{t.countryOther}</option>
            </select>
            <input className="amor-input" style={inputStyle} placeholder={t.org} value={form.org} onChange={(e) => setForm({ ...form, org: e.target.value })} />
            <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
              <input className="amor-input" style={{ ...inputStyle, flex: 1, minWidth: 200 }} placeholder={t.email} type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
              <input className="amor-input" style={{ ...inputStyle, flex: 1, minWidth: 200 }} placeholder={t.phone} value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} />
            </div>
            <label style={{ display: "flex", gap: 10, alignItems: "flex-start", fontSize: 14, fontWeight: 700, margin: "2px 0 6px", cursor: "pointer" }}>
              <input type="checkbox" checked={form.consent} onChange={(e) => setForm({ ...form, consent: e.target.checked })} style={{ width: 22, height: 22, accentColor: C.magenta, marginTop: 1 }} />
              <span>{t.consent}</span>
            </label>
            <p style={{ fontSize: 13, opacity: 0.7, margin: "0 0 18px" }}>{t.required}</p>
            <div style={{ display: "flex", gap: 16, alignItems: "center", flexWrap: "wrap" }}>
              <div style={{ opacity: canGo ? 1 : 0.4, pointerEvents: canGo ? "auto" : "none" }}>
                <BigButton onClick={submitJoin}>{t.letsTalk} →</BigButton>
              </div>
              <button className="amor-btn amor-body" onClick={() => setScreen("home")} style={{ background: "none", border: "none", fontSize: 15, fontWeight: 800, textDecoration: "underline", color: C.purple }}>
                {t.skip}
              </button>
            </div>
          </div>
          <Mascot pose="chat" size={190} style={{ alignSelf: "flex-end" }} />
        </div>
      </Frame>
    );
  }

  /* ---- HOME ---- */
  if (screen === "home") {
    return (
      <Frame {...frameProps}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "18px 24px 0", gap: 10, flexWrap: "wrap" }}>
          <div className="amor-script" style={{ fontSize: 40, color: C.magenta }}>Amor!</div>
          <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
            <LangToggle lang={lang} setLang={setLang} />
            {chat.length > 0 && (
              <button className="amor-btn amor-display" onClick={() => setScreen("answer")} style={{ background: C.magenta, border: `3px solid ${C.plum}`, borderRadius: 999, padding: "8px 16px", fontSize: 14, color: C.white }}>
                💬 {t.backChat}
              </button>
            )}
            <button className="amor-btn amor-display" onClick={resetForNewVisitor} style={{ background: C.white, border: `3px solid ${C.plum}`, borderRadius: 999, padding: "8px 16px", fontSize: 14, color: C.plum }}>
              {t.newVisitor}
            </button>
          </div>
        </div>
        <div style={{ flex: 1, padding: "14px 24px 8px", maxWidth: 1100, width: "100%", margin: "0 auto", boxSizing: "border-box" }}>
          <div className="amor-rise amor-display" style={{ fontSize: "clamp(36px, 5.5vw, 64px)", lineHeight: 1, color: C.plum }}>
            {visitor?.name ? `${visitor.name.split(" ")[0].toUpperCase()}, ` : ""}{t.homeTitle}
          </div>
          <p className="amor-rise-2" style={{ fontSize: 17, fontWeight: 700, margin: "8px 0 18px" }}>{t.homeSub}</p>

          <div className="amor-rise-2" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(230px, 1fr))", gap: 13 }}>
            {t.topics.map((topic, i) => {
              const bgs = [C.magenta, C.white, C.purple, C.white];
              const bg = bgs[i % 4];
              const fg = bg === C.white ? C.plum : C.white;
              return (
                <button
                  key={i}
                  className="amor-btn amor-tile"
                  onClick={() => ask(topic.q)}
                  style={{ textAlign: "left", background: bg, color: fg, border: `3px solid ${C.plum}`, borderRadius: 22, boxShadow: `0 5px 0 ${C.plum}`, padding: "16px 16px 14px", transform: `rotate(${i % 2 === 0 ? -0.5 : 0.5}deg)` }}
                >
                  <div className="amor-display" style={{ fontSize: 26, marginBottom: 4, opacity: 0.9 }}>{topic.icon}</div>
                  <div className="amor-body" style={{ fontSize: 17, fontWeight: 800, lineHeight: 1.2 }}>{topic.q}</div>
                </button>
              );
            })}
          </div>

          <div className="amor-rise-3" style={{ display: "flex", gap: 12, marginTop: 20, maxWidth: 820, flexWrap: "wrap" }}>
            <input
              className="amor-input"
              style={{ flex: 1, minWidth: 240, padding: "16px 20px", fontSize: 19, border: `3px solid ${C.plum}`, background: C.white, boxSizing: "border-box" }}
              placeholder={t.askPlaceholder}
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter" && draft.trim()) { ask(draft); setDraft(""); } }}
            />
            <BigButton small onClick={() => { if (draft.trim()) { ask(draft); setDraft(""); } }}>{t.askBtn}</BigButton>
            <BigButton small color={C.yellow} textColor={C.plum} onClick={startQuiz}>♥ {t.quizBtn}</BigButton>
            <BigButton small color={C.purple} onClick={() => setShowVideos(0)}>▶ {t.videosBtn}</BigButton>
          </div>

          <div className="amor-rise-3" style={{ display: "flex", gap: 16, alignItems: "center", marginTop: 20, background: C.white, border: `3px solid ${C.plum}`, borderRadius: 24, padding: "14px 20px", flexWrap: "wrap" }}>
            <Mascot pose="chat" size={90} />
            <div style={{ flex: 1, minWidth: 260 }}>
              <div className="amor-display" style={{ fontSize: 20, color: C.magenta }}>{t.teamTitle}</div>
              <div style={{ fontSize: 14.5, fontWeight: 700, lineHeight: 1.35 }}>{t.teamBody}</div>
              <div style={{ fontSize: 14.5, fontWeight: 800, lineHeight: 1.35, marginTop: 6, color: C.purple }}>{t.teamJoy}</div>
            </div>
          </div>
        </div>
        {overlays}
      </Frame>
    );
  }

  /* ---- ANSWER: continuous conversation ---- */
  if (screen === "answer") {
    const lastYou = [...chat].reverse().find((m) => m.role === "you");
    const lastAmor = [...chat].reverse().find((m) => m.role === "amor");
    const pleasureQ = /pleasure|prazer|fun|gostoso|sexy/i.test(lastYou?.text || "");
    const guideRelevant = /insert|inser(ir|ção)|how (do|to)[^.?!]*use|c[oó]mo[^.?!]*(uso|usar|usarme|usarte)|como[^.?!]*(uso|usar)|coloc(o|ar|a)|put (you|me) (on|in)|passo a passo|step.by.step|steps|demonstra|tumia|ninakutumiaje|ingiza|hatua|utilis|ins[eé]r|étape|shandis|pinza|nhanho|sebenzis|faka|nyathelo|gb[éẹ]s[ẹe]|lò (mí|ọ́)|ìlò/i.test(
      (lastYou?.text || "") + " " + (lastAmor?.text || "")
    );
    return (
      <Frame bgImage={IMG_BG} {...frameProps}>
        {/* soft overlay so the chat reads clearly over Rio */}
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(251,227,240,.55) 0%, rgba(251,227,240,.88) 34%, rgba(251,227,240,.94) 100%)", pointerEvents: "none" }} />
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "16px 24px 0", position: "relative", zIndex: 2, gap: 10, flexWrap: "wrap" }}>
          <div className="amor-script" style={{ fontSize: 40, color: C.deep, textShadow: `2px 2px 0 ${C.white}` }}>Amor!</div>
          <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
            <LangToggle lang={lang} setLang={setLang} />
            <button className="amor-btn amor-display" onClick={sayGoodbye} disabled={loading} style={{ background: C.magenta, border: `3px solid ${C.plum}`, borderRadius: 999, padding: "8px 18px", fontSize: 14, color: C.white, boxShadow: `0 4px 0 ${C.plum}`, opacity: loading ? 0.5 : 1 }}>
              👋 {t.goodbye}
            </button>
          </div>
        </div>

        {/* Amor herself, cheering along on wide screens */}
        <div className="amor-side">
          <Mascot pose={loading ? "think" : pleasureQ ? "cheer" : "chat"} size={210} />

          {pleasureQ && !loading && (
            <>
              {[0, 1, 2].map((i) => (
                <div key={i} style={{ position: "absolute", bottom: 60 + i * 20, left: 20 + i * 55, fontSize: 28, animation: `heartFloat 2.${i}s ease-out ${i * 0.4}s infinite` }}>💗</div>
              ))}
            </>
          )}
        </div>

        {/* the conversation */}
        <div style={{ flex: 1, overflowY: "auto", padding: "14px 20px 6px", position: "relative", zIndex: 1 }}>
          <div style={{ maxWidth: 760, margin: "0 auto", display: "flex", flexDirection: "column", gap: 12 }}>
            {chat.map((m, i) =>
              m.role === "you" ? (
                <div key={i} className="amor-rise" style={{ alignSelf: "flex-end", maxWidth: "82%", background: C.magenta, color: C.white, border: `3px solid ${C.plum}`, borderRadius: "22px 22px 4px 22px", boxShadow: `0 4px 0 ${C.plum}`, padding: "12px 18px" }}>
                  <div className="amor-body" style={{ fontSize: 11, fontWeight: 800, textTransform: "uppercase", letterSpacing: ".14em", opacity: 0.85 }}>
                    {visitor?.name ? visitor.name.split(" ")[0] : t.youLabel}
                  </div>
                  <div className="amor-display" style={{ fontSize: "clamp(17px, 2.2vw, 21px)", lineHeight: 1.2 }}>{m.text}</div>
                </div>
              ) : (
                <div key={i} className="amor-rise" style={{ alignSelf: "flex-start", maxWidth: "88%", display: "flex", gap: 10, alignItems: "flex-end" }}>
                  <img src={IMG_AMOR} alt="" aria-hidden="true" style={{ width: 44, height: "auto", flexShrink: 0, filter: "drop-shadow(0 3px 5px rgba(74,16,51,.3))" }} />
                  <div style={{ background: C.white, border: `3px solid ${C.plum}`, borderRadius: "22px 22px 22px 4px", boxShadow: `0 4px 0 ${C.deep}`, padding: "13px 18px" }}>
                    <div className="amor-script" style={{ fontSize: 20, color: C.magenta, lineHeight: 1 }}>Amor</div>
                    <div className="amor-body" style={{ fontSize: "clamp(16.5px, 2vw, 20px)", fontWeight: 700, lineHeight: 1.42, whiteSpace: "pre-wrap", color: C.plum, marginTop: 4 }}>{m.text}</div>
                  </div>
                </div>
              )
            )}
            {loading && (
              <div className="amor-rise" style={{ alignSelf: "flex-start", display: "flex", gap: 10, alignItems: "center" }}>
                <FlowerSpin size={44} spinning />
                <div className="amor-display" style={{ fontSize: 22, color: C.deep, animation: "amorBlink 1.2s ease-in-out infinite", textShadow: `1px 1px 0 ${C.white}` }}>
                  {t.thinking[Math.floor(Math.random() * t.thinking.length)]}
                </div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>
        </div>

        {/* stay right here: type the next question or tap a quick action */}
        <div style={{ position: "relative", zIndex: 2, padding: "8px 20px 10px" }}>
          <div style={{ maxWidth: 760, margin: "0 auto" }}>
            <div style={{ display: "flex", gap: 10 }}>
              <input
                className="amor-input"
                style={{ flex: 1, minWidth: 0, padding: "14px 18px", fontSize: 18, border: `3px solid ${C.plum}`, background: C.white, boxSizing: "border-box" }}
                placeholder={t.askPlaceholder}
                value={draft}
                onChange={(e) => setDraft(e.target.value)}
                onKeyDown={(e) => { if (e.key === "Enter" && draft.trim() && !loading) { ask(draft); setDraft(""); } }}
              />
              <BigButton small onClick={() => { if (draft.trim() && !loading) { ask(draft); setDraft(""); } }}>{t.askBtn}</BigButton>
            </div>
            {!loading && guideRelevant && !guideAskEmail && (
              <div className="amor-rise-2" style={{ display: "flex", gap: 10, justifyContent: "center", flexWrap: "wrap", marginTop: 10 }}>
                <BigButton small color={C.magenta} onClick={() => setShowSteps(0)}>👀 {t.stepsBtn}</BigButton>
                <BigButton
                  small
                  color={C.deep}
                  onClick={() => {
                    if (visitor?.email && visitor.email.trim()) requestGuide(visitor.email);
                    else setGuideAskEmail(true);
                  }}
                >
                  📧 {t.guideBtn}
                </BigButton>
              </div>
            )}
            {!loading && guideAskEmail && (
              <div className="amor-rise-2" style={{ display: "flex", gap: 10, justifyContent: "center", marginTop: 10, flexWrap: "wrap" }}>
                <input
                  className="amor-input"
                  type="email"
                  style={{ flex: 1, minWidth: 220, maxWidth: 360, padding: "12px 16px", fontSize: 17, border: `3px solid ${C.plum}`, background: C.white, boxSizing: "border-box" }}
                  placeholder={t.guideEmailPh}
                  value={guideEmailDraft}
                  onChange={(e) => setGuideEmailDraft(e.target.value)}
                  onKeyDown={(e) => { if (e.key === "Enter") requestGuide(guideEmailDraft); }}
                  autoFocus
                />
                <BigButton small color={C.deep} onClick={() => requestGuide(guideEmailDraft)}>{t.guideSend}</BigButton>
              </div>
            )}
            {!loading && (
              <div className="amor-rise-2" style={{ display: "flex", gap: 10, justifyContent: "center", flexWrap: "wrap", marginTop: 10 }}>
                <BigButton small color={C.purple} onClick={() => ask(t.tellMoreQuery)}>{t.moreDetail}</BigButton>
                <button className="amor-btn amor-display" onClick={() => setScreen("home")} style={{ background: C.white, border: `3px solid ${C.plum}`, borderRadius: 999, color: C.plum, padding: "10px 20px", fontSize: 15 }}>
                  {t.another}
                </button>
                <BigButton small color={C.yellow} textColor={C.plum} onClick={startQuiz}>♥ {t.quizBtn}</BigButton>
                <button className="amor-btn amor-display" onClick={() => setShowVideos(0)} style={{ background: C.white, border: `3px solid ${C.plum}`, borderRadius: 999, color: C.purple, padding: "10px 20px", fontSize: 15 }}>
                  ▶ {t.videosBtn}
                </button>
              </div>
            )}
          </div>
        </div>
        {overlays}
      </Frame>
    );
  }

  /* ---- QUIZ ---- */
  if (screen === "quiz") {
    return (
      <Frame {...frameProps}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "18px 24px 0" }}>
          <div className="amor-script" style={{ fontSize: 40, color: C.magenta }}>Amor!</div>
          <LangToggle lang={lang} setLang={setLang} />
        </div>
        <div style={{ flex: 1, padding: "10px 24px", maxWidth: 1060, width: "100%", margin: "0 auto", boxSizing: "border-box", textAlign: "center" }}>
          <div className="amor-rise amor-display" style={{ fontSize: "clamp(30px, 4.5vw, 50px)", color: C.magenta, lineHeight: 1 }}>
            ♥ {t.quizTitle} ♥
          </div>
          <p className="amor-rise-2" style={{ fontSize: 16, fontWeight: 800, margin: "8px 0 4px" }}>{t.quizSub}</p>
          <p className="amor-rise-2" style={{ fontSize: 13.5, fontWeight: 700, margin: "0 0 14px", opacity: 0.75 }}>{t.quizReset}</p>

          <div className="amor-rise-2" style={{ display: "flex", flexWrap: "wrap", gap: 6, justifyContent: "center" }}>
            {quizCards.map((stepIdx) => {
              const pos = picks.indexOf(stepIdx);
              let state = null;
              if (Array.isArray(quizResult)) state = quizResult[quizCards.indexOf(stepIdx)] ? "right" : "wrong";
              if (quizResult === "win") state = "right";
              return (
                <HeartCard
                  key={stepIdx}
                  text={t.quizSteps[stepIdx]}
                  order={pos >= 0 ? pos + 1 : null}
                  state={state}
                  onClick={() => togglePick(stepIdx)}
                />
              );
            })}
          </div>

          {quizResult === "win" && (
            <div className="amor-rise" style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 14, marginTop: 8, flexWrap: "wrap" }}>
              <Mascot pose="cheer" size={130} />
              <div className="amor-display" style={{ fontSize: 22, color: C.magenta, maxWidth: 460, textAlign: "left" }}>{t.quizWin}</div>
            </div>
          )}
          {Array.isArray(quizResult) && (
            <div className="amor-rise amor-display" style={{ fontSize: 19, color: C.purple, marginTop: 10 }}>{t.quizLose}</div>
          )}

          <div style={{ display: "flex", gap: 14, justifyContent: "center", flexWrap: "wrap", marginTop: 16 }}>
            {quizResult !== "win" && (
              <div style={{ opacity: picks.length === 6 ? 1 : 0.4, pointerEvents: picks.length === 6 ? "auto" : "none" }}>
                <BigButton small onClick={checkQuiz}>{t.quizCheck}</BigButton>
              </div>
            )}
            <BigButton small color={C.purple} onClick={startQuiz}>{t.quizRetry}</BigButton>
            <BigButton small color={C.yellow} textColor={C.plum} onClick={() => setScreen("home")}>{t.another}</BigButton>
          </div>
        </div>
      </Frame>
    );
  }

  /* ---- ADMIN ---- */
  if (screen === "admin") {
    const leadHeaders = ["ts", "name", "country", "org", "email", "phone", "consent", "lang"];
    const qHeaders = ["ts", "lang", "visitor", "country", "question", "answer"];
    const gHeaders = ["ts", "name", "country", "email", "lang"];
    return (
      <Frame {...frameProps}>
        <div style={{ flex: 1, padding: "30px", maxWidth: 1000, margin: "0 auto", width: "100%", boxSizing: "border-box" }}>
          <div className="amor-display" style={{ fontSize: 40, color: C.magenta }}>{t.adminTitle}</div>
          <div style={{ display: "flex", gap: 24, margin: "18px 0", flexWrap: "wrap" }}>
            <div style={{ background: C.white, border: `3px solid ${C.plum}`, borderRadius: 20, padding: "18px 28px" }}>
              <div className="amor-display" style={{ fontSize: 48 }}>{leads.length}</div>
              <div style={{ fontWeight: 800 }}>{t.adminLeads}</div>
            </div>
            <div style={{ background: C.white, border: `3px solid ${C.plum}`, borderRadius: 20, padding: "18px 28px" }}>
              <div className="amor-display" style={{ fontSize: 48 }}>{qLog.length}</div>
              <div style={{ fontWeight: 800 }}>{t.adminQs}</div>
            </div>
            <div style={{ background: C.white, border: `3px solid ${C.plum}`, borderRadius: 20, padding: "18px 28px" }}>
              <div className="amor-display" style={{ fontSize: 48 }}>{guideReqs.length}</div>
              <div style={{ fontWeight: 800 }}>{t.adminGuides}</div>
            </div>
          </div>
          <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginBottom: 22 }}>
            <BigButton small onClick={() => downloadCSV(leads, leadHeaders, "amor_visitors.csv")}>{t.exportLeads}</BigButton>
            <BigButton small onClick={() => downloadCSV(qLog, qHeaders, "amor_questions.csv")}>{t.exportQs}</BigButton>
            <BigButton small onClick={() => downloadCSV(guideReqs, gHeaders, "amor_guide_requests.csv")}>{t.exportGuides}</BigButton>
            <BigButton small color={C.purple} onClick={() => setScreen("attract")}>{t.close}</BigButton>
            <button
              className="amor-btn amor-body"
              onClick={async () => {
                if (window.confirm(t.confirmClear)) { await saveLeads([]); await saveQLog([]); await saveGuideReqs([]); }
              }}
              style={{ background: "none", border: `3px solid ${C.deep}`, borderRadius: 999, color: C.deep, fontWeight: 800, padding: "10px 20px" }}
            >
              {t.clearData}
            </button>
          </div>
          <div style={{ background: C.white, border: `3px solid ${C.plum}`, borderRadius: 16, padding: 16, maxHeight: 300, overflow: "auto", fontSize: 14 }}>
            {leads.slice().reverse().map((l, i) => (
              <div key={i} style={{ borderBottom: `1px solid ${C.pinkMid}`, padding: "6px 0" }}>
                <b>{l.name}</b> · {l.country} · {l.org} · {l.email} · {l.phone} {l.consent ? "· ✔ consent" : ""}
              </div>
            ))}
            {leads.length === 0 && <div style={{ opacity: 0.6 }}>...</div>}
          </div>
        </div>
      </Frame>
    );
  }

  return null;
}
